#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# 在仓库根目录运行：scripts/setup-oauth.sh
# 配置用户登录（GitHub、Google 的 OAuth 应用）、后台 key 和封禁名单用的密钥，以及相关开关，写进 .env，
# 然后重启后端并用真实账号走一遍。可以随时 Ctrl-C，重新运行时已保存的值按回车即可保留。

cd "$(dirname "$0")/.."

TOTAL_STAGES=8

banner "Eidolon-GIM 登录配置"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "网站地址"
say "登录的回调地址由网站地址决定。"
say "公开部署填域名（例如 eidolon.example.com，不带 https://）；本地开发直接回车留空。"
ask EIDOLON_DOMAIN "网站域名："
EIDOLON_DOMAIN="${EIDOLON_DOMAIN#https://}"
EIDOLON_DOMAIN="${EIDOLON_DOMAIN%/}"
if [[ -n "$EIDOLON_DOMAIN" ]]; then
  SITE="https://$EIDOLON_DOMAIN"
  COMPOSE=(docker compose -f docker-compose.prod.yml)
else
  SITE="http://localhost:3000"
  COMPOSE=(docker compose)
fi
write_env EIDOLON_DOMAIN "$EIDOLON_DOMAIN"
say ""
say "网站地址：$SITE"
say "GitHub 回调地址：$SITE/api/auth/github/callback"
say "Google 回调地址：$SITE/api/auth/google/callback"
note "后面几步会用到这两个回调地址。"
pause "按回车继续"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "GitHub OAuth App"
open_url "https://github.com/settings/applications/new"
if [[ -n "$EIDOLON_DOMAIN" ]]; then
  step "Application name：用户在授权页上看到的名字，和网站标题一样，例如 Eidolon-GIM"
else
  step "Application name：开发用的单独建一个，例如 Eidolon-GIM (dev)"
fi
step "Homepage URL：$SITE"
step "Application description：一两句话说明网站是做什么的，会显示在授权页上"
step "Authorization callback URL：$SITE/api/auth/github/callback"
step "不用勾选 Enable Device Flow，点 Register application"
step "在应用页复制 Client ID"
ask GITHUB_CLIENT_ID "粘贴 Client ID："
step "点 Generate a new client secret，复制生成的 secret（只显示这一次）"
ask_secret GITHUB_CLIENT_SECRET "粘贴 Client secret（输入不显示）："
write_env GITHUB_CLIENT_ID "$GITHUB_CLIENT_ID"
write_env GITHUB_CLIENT_SECRET "$GITHUB_CLIENT_SECRET"
step "在应用页 Upload new logo，选 docs/brand/oauth-logo-512.png；Badge background color 填 #1c2a4a，点 Update application"
pause "按回车继续"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Google：同意屏幕"
say "在 Google Cloud Console 为网站新建一个专用项目，不要和放 Gemini 等 API key 的项目共用。"
note "新版菜单在「Google Auth Platform」下；旧版叫「API 和服务 → OAuth 同意屏幕」。"
open_url "https://console.cloud.google.com/auth/branding"
step "品牌（Branding）：填应用名称和用户支持邮箱（会显示给用户）"
if [[ -n "$EIDOLON_DOMAIN" ]]; then
  step "同一页：应用徽标选 docs/brand/oauth-logo-120.png；首页、隐私权政策、服务条款填 $SITE、$SITE/privacy、$SITE/terms"
  step "已获授权的网域填顶级域名（$EIDOLON_DOMAIN 的最后两段，例如 example.com），保存"
fi
step "目标对象（Audience）：用户类型选「外部（External）」"
step "数据访问（Data access）：只添加 openid、…/auth/userinfo.email、…/auth/userinfo.profile 三个作用域"
if [[ -n "$EIDOLON_DOMAIN" ]]; then
  warn "对公众开放前，要在「目标对象」里点「发布应用」；只用这三个作用域不需要 Google 审核。"
  warn "没做品牌验证时，同意页只显示域名，不显示应用名称和图标。品牌验证的步骤见 docs/deploy.md「配置 OAuth 应用」，要等网站上线后再提交。"
else
  note "本地测试可以保持「测试」状态，把你自己的 Google 账号加进测试用户名单。"
fi
pause "同意屏幕配好后按回车"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Google：OAuth 客户端"
note "新版在「Google Auth Platform → 客户端」；旧版在「API 和服务 → 凭据 → 创建凭据 → OAuth 客户端 ID」。"
open_url "https://console.cloud.google.com/auth/clients/create"
step "应用类型：Web 应用（Web application）"
step "已获授权的重定向 URI：$SITE/api/auth/google/callback"
step "点创建，复制客户端 ID 和客户端密钥；最好也点「下载 JSON」，关掉对话框后就再也看不到密钥了"
ask GOOGLE_CLIENT_ID "粘贴客户端 ID："
ask_secret GOOGLE_CLIENT_SECRET "粘贴客户端密钥（输入不显示）："
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
pause "按回车继续"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "后台 key 和封禁名单的密钥"
if [[ -n "$(_existing EIDOLON_SECRET_KEY || true)" ]]; then
  say "EIDOLON_SECRET_KEY 已经有值，保持不变。"
  warn "不要更换它：换了以后，后台里保存的 key 无法解密，被删除的封禁用户也能重新注册。"
elif command -v openssl >/dev/null 2>&1; then
  write_env EIDOLON_SECRET_KEY "$(openssl rand -hex 32)"
  say "已生成。后台里保存的 key 用它加密，封禁名单也用它做哈希；用户的自带密钥只存在他们的浏览器里，跟它无关。"
  warn "请把 .env 备份好；这个值丢了或换了，后台里保存的 key 无法解密，封禁名单也对不上了。"
else
  warn "找不到 openssl，没有生成。可以在别处运行 openssl rand -hex 32，把结果粘贴进来："
  ask_secret EIDOLON_SECRET_KEY "粘贴 64 位十六进制字符串（输入不显示）："
  write_env EIDOLON_SECRET_KEY "$EIDOLON_SECRET_KEY"
fi
pause "按回车继续"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "开发登录与 Gemini 计费"
if [[ -n "$EIDOLON_DOMAIN" ]]; then
  write_env EIDOLON_DEV_LOGIN ""
  say "公开部署：开发登录已关闭（它让任何人都能冒充任何用户，打开时后端会拒绝启动）。"
  if [[ "$(_existing EMBEDDING_PROVIDER || true)" == "gemini" ]]; then
    say ""
    say "你用 Gemini 做向量化。免费层会把用户的记忆交给 Google 用于改进产品（ADR-0005 的修订）。"
    open_url "https://aistudio.google.com/usage"
    if confirm "这个 Gemini API key 所在的项目已经开通计费了吗？"; then
      write_env GEMINI_BILLING_ENABLED "1"
    else
      write_env GEMINI_BILLING_ENABLED ""
      warn "还没开计费：后端每次启动都会警告。开通后重新运行本向导，或者改用硅基流动（EMBEDDING_PROVIDER=siliconflow）。"
    fi
  fi
else
  if confirm "本地开发：要在登录页打开「开发登录」（按名字直接登录）吗？"; then
    write_env EIDOLON_DEV_LOGIN "1"
  else
    write_env EIDOLON_DEV_LOGIN ""
  fi
fi
pause "按回车继续"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "启动（或重启）后端"
say "新的设置要重启后端才生效。"
if command -v docker >/dev/null 2>&1 && docker info >/dev/null 2>&1; then
  say "将执行：${COMPOSE[*]} up -d"
  if confirm "现在执行吗？"; then
    "${COMPOSE[@]}" up -d
    note "看后端日志：${COMPOSE[*]} logs -f backend"
  else
    SKIPPED+=("重启后端：${COMPOSE[*]} up -d")
  fi
elif [[ -n "$EIDOLON_DOMAIN" ]]; then
  warn "这台机器上没有可用的 Docker。公开部署要在服务器上运行：${COMPOSE[*]} up -d"
  SKIPPED+=("在服务器上重启后端：${COMPOSE[*]} up -d")
else
  say "这台机器上没有可用的 Docker，可以不用它，直接在两个终端里分别启动："
  step "后端：cd backend && uv sync && uv run --env-file ../.env eidolon"
  step "前端：cd frontend && npm install && npm run dev"
  note "后端启动时会先调用一次对话模型做检查，CHAT_LLM_* 要填真实可用的值。"
fi
pause "后端起来后按回车"

# ── 8 ────────────────────────────────────────────────────────────────────
stage "用真实账号走一遍"
open_url "$SITE"
step "用 GitHub 登录，勾选同意条款和年满 13 岁，能看到角色列表"
step "设置页 → 登录方式 → 绑定 Google；退出登录，再用 Google 登录，是同一个用户（记忆、对话都在）"
step "设置页 → 自带密钥：填一个 LLM 密钥，试调通过；和角色说一句话，回复正常"
step "（配了语音时）打一次电话，说一句话，能听到角色的声音"
step "最后在设置页「删除我的全部数据」，把这个测试用户清掉"
note "登录失败时，登录页会写明原因；回调地址不匹配时，GitHub 或 Google 自己的页面会报 redirect_uri 错误。"
pause "都走通了就按回车"

finish
